15: /// The type describes that the inner transaction was already checked.
16: ///
17: /// All fields are private, and there is no constructor, so it is impossible to create the instance
18: /// of `Checked` outside the `fuel-tx` crate.
19: ///
20: /// The inner data is immutable to prevent modification to invalidate the checking.
21: ///
22: /// If you need to modify an inner state, you need to get inner values
23: /// (via the `Into<(Tx, Tx ::Metadata)>` trait), modify them and check again.
24: ///
25: /// Each ascending checked status includes all previous checks. So `Signature` means that
26: /// `Stateless` also is passed.
27: ///
28: /// # Dev note: Avoid serde serialization of this type. Since checked tx would need to be
29: /// re-validated on deserialization anyways, it's cleaner to redo the tx check.
30: #[derive(Debug, Clone, Eq, PartialEq, Hash)]
31: pub enum Checked<Tx: IntoChecked> {
32:     /// The transaction passed checks without the usage of the state of the blockchain.
33:     ///
34:     /// The rules defined in the specification:
35:     /// https://github.com/FuelLabs/fuel-specs/blob/master/specs/protocol/tx_format.md#transaction
36:     Stateless(Tx, Tx::Metadata),
37:     /// Signatures in the transaction are valid.
38:     Signatures(Tx, Tx::Metadata),
39: }
40: 
41: impl<Tx: IntoChecked> Checked<Tx> {
42:     pub fn transaction(&self) -> &Tx {
43:         match self {
44:             Checked::Stateless(tx, _) => tx,
45:             Checked::Signatures(tx, _) => tx,
46:         }
47:     }
48: 
49:     pub fn metadata(&self) -> &Tx::Metadata {
50:         match self {
51:             Checked::Stateless(_, metadata) => metadata,
52:             Checked::Signatures(_, metadata) => metadata,
53:         }
54:     }
55: 
56:     /// Performs full check, if not yet.
57:     pub fn check(self) -> Result<Checked<Tx>, CheckError> {
58:         match self {
59:             Checked::Stateless(transaction, metadata) => {
