+        ScalarType::Int16 => Some(size_of::<i16>()),
+        ScalarType::Int32 => Some(size_of::<i32>()),
+        ScalarType::Int64 => Some(size_of::<i64>()),
+        ScalarType::UInt16 => Some(size_of::<u16>()),
+        ScalarType::UInt32 => Some(size_of::<u32>()),
+        ScalarType::UInt64 => Some(size_of::<u64>()),
+        ScalarType::Float32 => Some(size_of::<f32>()),
+        ScalarType::Float64 => Some(size_of::<f64>()),
+        ScalarType::Date => Some(size_of::<i32>()),
+        ScalarType::Time => Some(2 * size_of::<u32>()),
+        ScalarType::Timestamp { precision: _ } => Some(3 * size_of::<u32>() + size_of::<i32>()),
+        ScalarType::TimestampTz { precision: _ } => Some(3 * size_of::<u32>() + size_of::<i32>()),
+        ScalarType::Interval => Some(2 * size_of::<i32>() + size_of::<i64>()),
+        ScalarType::Uuid => Some(size_of::<uuid::Bytes>()),
+        ScalarType::Oid => Some(size_of::<u32>()),
+        ScalarType::MzTimestamp => Some(size_of::<Timestamp>()),
+        ScalarType::MzAclItem => Some(MzAclItem::binary_size()),
+        ScalarType::AclItem => Some(AclItem::binary_size()),
+        ScalarType::Numeric { .. }
