+/// TrueType glyph scaler for a specific font and configuration.
+pub struct Scaler<'a> {
+    /// Backing context.
+    context: &'a mut Context,
+    /// Current font data.
+    font: Font<'a>,
+    /// Font identifier for the hinting cache.
+    font_id: Option<u64>,
