+                let base_denom = Denom::from_str(last_part)?;
+                let trace_path = TracePath::try_from(parts)?;
+                (base_denom, trace_path)
+            }
+        };
+
+        Ok(Self {
+            trace_path,
+            base_denom,
+        })
+    }
