+    fn new(queued: QueuedTelemetry) -> Self {
+        Self { queued_at: queued.queued_at, started_at: Instant::now() }
+    }
+}
+
+#[derive(Clone, Copy)]
+pub struct CompletedTelemetry {
+    pub queued_at: Instant,
+    pub started_at: Instant,
+    pub completed_at: Instant,
+}
+
