+
+    pub telemetry: InProgressTelemetry,
+}
+
+impl InProgressSync {
+    fn new(queued: QueuedSync, progress: mpsc::Receiver<SyncProgress>) -> Self {
+        Self { progress, telemetry: InProgressTelemetry::new(queued.telemetry) }
+    }
+}
+
+pub struct CompletedLoad {
